import stylelint from "stylelint";
import { namespaces } from "../../syntaxes/index.js";
import { addNamespace } from "../addNamespace/index.js";
import { asksForTheCharsetRule, CHARSET_RULE_MESSAGE } from "../asksForTheCharsetRule/index.js";
import { refuseConflictingSettings } from "../conflictingSettings/index.js";
import { copyReadingTheRoot } from "../copyReadingTheRoot/index.js";
import { deferCheck, deferFinalCheck, deferHeadCheck, defersToRunEnd, flushDeferredChecks, lastConfiguredPluginRule, linenessRank, registerPluginRule } from "../defersToRunEnd/index.js";
import { pinInventedRaws, unpinAllPinnedRoots, unpinUnwritten } from "../pinInventedRaws/index.js";
import { notePinReads } from "../readsPinnedRaws/index.js";
import { report } from "../report/index.js";
let { utils: { ruleMessages } } = stylelint;
/**
 * Names a rule's messages before a rule name closes them under each namespace.
 * @param messages - Each message by key.
 * @returns The same messages, typed as written.
 */
export function defineMessages(messages) {
    return messages;
}
/** The roots refused already: one warning per stylesheet, not one per rule. */
let refused = new WeakSet();
/** The roots asked for the `@charset` rule already: one warning per stylesheet, not one per rule. */
let askedForTheCharsetRule = new WeakSet();
/**
 * Turns a rule definition into a factory over a syntax, which names the rule under the syntax's namespace, closes the messages with that name, and refuses a root the syntax does not accept in front of the rule: with one warning naming the namespaces that would read it, or without a word where a configured copy of the rule under one of them does.
 * @param definition - The rule's definition.
 * @returns The factory, whose result `createPlugin` takes.
 */
export function defineRule(definition) {
    let { shortName, meta, messages, rule, defersToRunEnd: readsEveryLine, checksAheadOfLineness } = definition;
    return (syntax) => {
        let ruleName = addNamespace(shortName, syntax.namespace);
        registerPluginRule(ruleName);
        let scopedMessages = ruleMessages(ruleName, messages);
        let { refusal, charset } = ruleMessages(ruleName, {
            refusal: (names) => (names ? `The "${ruleName}" rule does not read a stylesheet parsed with this syntax; the ${names} rules do` : `The "${ruleName}" rule does not read a stylesheet parsed with this syntax`),
            charset: CHARSET_RULE_MESSAGE,
        });
        /**
         * The rule as Stylelint calls it.
         * @param primary - The configured primary, passed through unread.
         * @param secondaryOptions - The configured secondaries, passed through unread.
         * @returns The check, unless the syntax refuses the root.
         */
        function scoped(primary, secondaryOptions) {
            let check = rule({ ruleName, messages: scopedMessages, syntax }, primary, secondaryOptions);
            let rank = linenessRank(shortName, syntax.namespace, typeof primary === `string` ? primary : ``);
            /**
             * What the rule does at a turn, refusal included, so a deferred rule refuses as an undeferred one would.
             * @param root - The stylesheet of the turn.
             * @param result - The lint result the warnings go into.
             */
            function guarded(root, result) {
                if (syntax.accepts(root, result)) {
                    // A root is read by one copy of a rule, the other copies of it yielding without a word
                    if (copyReadingTheRoot(shortName, root, result) !== ruleName)
                        return;
                    // No rule of the plugin judges the spelling of a `@charset`, and the core rule that does is not on: one warning per file, in front of the first rule reading it
                    if (!askedForTheCharsetRule.has(root) && asksForTheCharsetRule(root, result, syntax)) {
                        askedForTheCharsetRule.add(root);
                        report({ message: charset, node: root, index: 0, endIndex: 0, result, ruleName });
                    }
                    syntax.restore(root, result);
                    // A node another plugin's rule built carries none of the raws the rules read and write, and PostCSS invents them in print out of its neighbors
                    pinInventedRaws(root);
                    // What the rule reads of those raws is the rule's answer, and the plugin stands by it where a rule of another plugin changes the tree behind it
                    notePinReads(root, () => check(root, result));
                    return;
                }
                // A configured copy of another namespace reads the root and says whatever there is to say; the warning is for a root no configured copy reads
                if (copyReadingTheRoot(shortName, root, result) !== undefined || refused.has(root))
                    return;
                refused.add(root);
                // The warning names the namespaces that do read the root
                let takers = namespaces.filter((namespace) => namespace.accepts(root, result)).map((namespace) => `"@stylistic/${namespace.namespace}/"`).join(` and `);
                report({ message: refusal, messageArgs: [takers], node: root, index: 0, endIndex: 0, result, ruleName });
            }
            return (root, result) => {
                refuseConflictingSettings(root, result);
                let last = lastConfiguredPluginRule(result);
                // Deferred (to read lineness, or every line) only where a flush is sure to come: under a configuration the plugin cannot read the check runs where it stands. Its place is the plugin's to decide, not the configuration's
                if (readsEveryLine && last !== undefined) {
                    if (checksAheadOfLineness)
                        deferHeadCheck(root, rank, () => guarded(root, result));
                    deferFinalCheck(root, rank, () => guarded(root, result));
                }
                else if (defersToRunEnd(primary) && last !== undefined)
                    deferCheck(root, rank, () => guarded(root, result));
                else
                    guarded(root, result);
                if (ruleName !== last)
                    return;
                try {
                    flushDeferredChecks(root);
                }
                catch (error) {
                    // A check of the plugin's own cut the run short: the run has ended, so every root the run pinned is unwound, not only this one — a root the throwing rule never reached must not stay wrapped
                    unpinAllPinnedRoots();
                    throw error;
                }
                finally {
                    // Every rule of the plugin has read the root, and a rule of another plugin listed behind may yet fill a block; a run a deferred check of the plugin's own cut short has no other place to unpin in, and the tree it still holds is the wrapper's
                    unpinUnwritten(root);
                }
            };
        }
        return Object.assign(scoped, { ruleName, messages: scopedMessages, meta });
    };
}
